def source(n):
    for i in range(n): yield {"id": i, "v": i * 2}
def evens(recs):
    for r in recs:
        if r["v"] % 4 == 0: yield r
total = sum(1 for _ in evens(source(1000000)))
print("matching records:", total)
assert total == 500000

vals = sorted([i*i % 97 for i in range(500)])
def quantile(q):
    i = q * (len(vals)-1); lo = int(i)
    return vals[lo] + (vals[lo+1]-vals[lo]) * (i-lo)
print("p50:", quantile(0.5), "p99:", quantile(0.99))
assert quantile(0.5) <= quantile(0.99)

from collections import OrderedDict
cache = OrderedDict()
def get(k):
    if k in cache: cache.move_to_end(k); return cache[k]
    return None
def put(k, v):
    cache[k] = v; cache.move_to_end(k)
    if len(cache) > 3: cache.popitem(last=False)
for k in ["a", "b", "c", "d", "a"]:
    put(k, k.upper()) if get(k) is None else None
print("cache keys:", list(cache))
assert list(cache) == ["c", "d", "a"]

def chunks(n, size):
    for i in range(0, n, size): yield range(i, min(i+size, n))
peak = 0
for ch in chunks(10000, 500):
    batch = list(ch); peak = max(peak, len(batch)); s = sum(batch)
print("peak batch:", peak)
assert peak == 500
